diff --git a/src/reservation-priority.mjs b/src/reservation-priority.mjs
index 6666666..7777777 100644
--- a/src/reservation-priority.mjs
+++ b/src/reservation-priority.mjs
@@ -1,11 +1,11 @@
 export function cancelUntilFits(reservations, available) {
-  const ordered = [...reservations].sort((a, b) => b.createdAt - a.createdAt);
+  const ordered = [...reservations].sort((a, b) => a.createdAt - b.createdAt);
   const cancelled = [];
   let total = reservations.reduce((sum, item) => sum + item.grams, 0);
   for (const item of ordered) {
     if (total <= available) break;
     total -= item.grams;
     cancelled.push(item.id);
   }
   return cancelled;
 }
